; CYCLES_FORWARD_BRANCHES
; AERIA HAIL  -- generated by hail/gen.py, do not edit.
; The Balloon Shop's hailstones (MoreWeather.h, Hail): now and then a stone is born -- a slice of
; what is playing, 5 .. 30 ms of (L + R)/2, enveloped (0.5 ms rise, (1 - t)^2 fall), read at
; 0.5 / 1 / 1 / 1.5 / 2 x speed -- hits hard somewhere between the speakers and bounces 4 .. 8
; times, each bounce sooner (x 0.62 .. 0.78) and quieter (x 0.72), like a ball dropped on a table.
; The stones are ADDED to the dry sound.
;
;  knob 0 AMT   the weather's fade 0..127 = 0..1: how often a stone is born (x RATE). At 0 none are
;               born; the ones in the air finish
;  knob 1 RATE  stones a second at full amount: 2.2 x 2^((v - 64)/16)   (64 = the plugin)
;  knob 2 SIZE  slice length x 2^((v - 64)/64)   (64 = the plugin's 5 .. 30 ms)
;  knob 3 BNCE  how well it bounces: the gap ratio 0.62 .. 0.78 shifted by (v - 64)/64 x 0.25, held to 0.2 .. 0.95
;  knob 4 WDTH  how wide the stones fall: pan = random x v/127 (114 = the plugin's 0.9)
;
; AMT 0 and no stone in the air: REST (returns at once, output = input bit for bit).
; A stone records its slice when it is born (1365 words of its own, envelope included), then plays
; it at every hit; hits start on a call (16 frames), the gaps keep their fraction. Rates 0.5 and
; 1.5 land on half frames every second frame: read with the plugin's Hermite, which there is
; (9 (b0 + b1) - (b-1 + b2))/16; whole frames are read as they are. 6 stones.
;
; X: 8190 words from the word X:$213 points to (an X address on this effect); no alignment.
; r7: 00 XB 01 RNG 02 NACT 03 RLAST 04 THR 05 SZ 06 T1 07 T2; stones at r7 + $40 + 20 k: 00 MODE 01 PTR 02 CNT 03 U 04 UINC 05 ATK 06 ATKI 07 RATE2 08 LB 09 TNEXT 0a GAP 0b RATIO 0c HITS 0d HG 0e PL 0f PR 10 BASE
;     (while a stone sounds, U / UINC hold this hit's two gains)

init:
        move    #>$ffffff,m4
        move    r7,r4
        clr     a
        do      #192,>hlzero
        move    a,x:(r4)+
hlzero:
        nop
        move    x:>$213,r4
        nop
        move    x:(r4),a
        move    a,x:(r7+$00)
        move    #>$004a11,b             ; the plugin's seed
        move    b,x:(r7+$01)
        move    #>$ffffff,b
        move    b,x:(r7+$03)
        move    r7,r5
        move    #>$000040,n5
        move    #>$000555,x0
        move    (r5)+n5
        move    #>$000014,n5
        do      #>$000006,>hlbases
        move    a,x:(r5+$10)
        add     x0,a
        move    (r5)+n5
hlbases:
        nop
        rts
proc:
        move    x:(r6),a
        tst     a
        bne     hlgo
        move    x:(r7+$02),a
        tst     a
        bne     hlfly
        rts                             ; REST: nothing touched
hlgo:
; ---- RATE (only when it moved): chance a call at full amount = 2.2 x 16/fs x 2^((v - 64)/16)
        move    x:(r6+$1),a
        move    x:(r7+$03),x0
        cmp     x0,a
        beq     hlrsame
        move    a,x:(r7+$03)
        move    #>$7f0000,b
        sub     a,b
        asr     #$2,b,b
        move    b1,a
        bsr     hlexp
        move    b,x0
        move    #>$0193e4,y0
        mpy     y0,x0,a
        move    a,x:(r7+$04)
hlrsame:
; ---- a new stone?
        move    x:(r6),x0
        move    x:(r7+$04),y0
        mpy     y0,x0,a
        move    a,x1
        bsr     hlrand
        cmp     x1,a
        bge     hlfly
        move    r7,r5
        move    #>$000040,n5
        move    #>$0,r4
        move    (r5)+n5
        move    #>$000014,n5
        do      #>$000006,>hlfind
        move    x:(r5),a
        tst     a
        bne     hlbusy
        move    r5,r4
hlbusy:
        move    (r5)+n5
        nop
hlfind:
        move    r4,a
        tst     a
        beq     hlfly                   ; all in the air: no stone this time (the plugin does the same)
        move    r4,r5
        bsr     hlborn
hlfly:
; ======== the stones ========
        move    r0,r2
        move    r7,r5
        move    #>$000040,n5
        nop
        move    (r5)+n5
        move    #>$000014,n5
        do      #>$000006,>hlstones
        move    x:(r5),a
        tst     a
        beq     hlnext
        cmp     #>$000001,a
        bne     hllive
; ---- being born: 16 more words of (L + R)/2 x min(1, attack) x (1 - t)^2 into its slice
        move    r2,r0
        move    x:(r5+$01),r1
        move    x:(r5+$03),b
        move    x:(r5+$04),y1
        do      #16,>hlrec
        move    x:(r0)+,a
        move    x:(r0)+,x0
        add     x0,a
        asr     a
        move    a,x1
        sub     y1,b
        move    #>$0,y0
        tmi     y0,b
        move    b,x0
        mpy     x0,x0,a
        move    a,x0
        move    x:(r5+$05),a
        move    x:(r5+$06),y0
        add     y0,a
        move    a,y0
        move    y0,x:(r5+$05)
        mpy     y0,x0,a
        move    a,x0
        mpy     x1,x0,a
        move    a,x:(r1)+
hlrec:
        nop
        move    b,x:(r5+$03)
        move    r1,x:(r5+$01)
        move    x:(r5+$02),a
        sub     #>$1,a
        move    a,x:(r5+$02)
        bgt     hlnext
        move    #>$2,a                  ; recorded: in the air, the first hit on the next call
        move    a,x:(r5)
        clr     a
        move    a,x:(r5+$09)
        move    a,x:(r5+$02)
        bra     hlnext
hllive:
        move    x:(r5+$09),a
        sub     #>$10,a
        move    a,x:(r5+$09)
        move    x:(r5+$02),b
        tst     b
        bne     hlplay                  ; a hit is sounding
        tst     a
        bgt     hlnext                  ; waiting for the next
        move    x:(r5+$0c),b
        tst     b
        bne     hlhit
        move    b,x:(r5)                ; its last bounce is over
        move    x:(r7+$02),b
        sub     #>$1,b
        move    b,x:(r7+$02)
        bra     hlnext
hlhit:
        sub     #>$1,b
        move    b,x:(r5+$0c)
        move    x:(r5+$0a),x0
        add     x0,a
        move    a,x:(r5+$09)               ; the next one a gap later, the gap x ratio
        move    x:(r5+$0b),y0
        mpy     y0,x0,a
        move    a,x:(r5+$0a)
        move    x:(r5+$0d),x0                 ; this hit's level on each side, the next x 0.72
        move    x:(r5+$0e),y0
        mpy     y0,x0,a
        move    a,x:(r5+$03)
        move    x:(r5+$0f),y0
        mpy     y0,x0,a
        move    a,x:(r5+$04)
        move    #>$5c28f6,y0
        mpy     y0,x0,a
        move    a,x:(r5+$0d)
        move    x:(r5+$08),a
        move    a,x:(r5+$02)
        move    x:(r5+$10),a
        add     #>$1,a
        move    a,x:(r5+$01)
hlplay:
        move    r2,r0
        move    x:(r5+$01),r1
        move    x:(r5+$03),y0
        move    x:(r5+$04),y1
        move    x:(r5+$07),a
        jclr    #0,a1,hlwhole
; rates 0.5 and 1.5: a whole frame, then the half frame between (Hermite at 0.5)
        move    a1,n1
        sub     #>$3,a
        asr     a
        move    a1,n3
        do      #8,>hlpairs
        move    x:(r1),x0
        move    x:(r0),a
        mac     y0,x0,a
        mac     y0,x0,a
        move    a,x:(r0)+
        move    x:(r0),a
        mac     x0,y1,a
        mac     x0,y1,a
        move    a,x:(r0)+
        move    r1,r3
        nop
        lua     (r3)+n3,r3
        nop
        move    x:(r3)+,b
        move    x:(r3)+,a
        move    x:(r3)+,x0
        add     x0,a
        move    x:(r3)+,x0
        add     x0,b
        asr     a
        asr     b
        move    a,x0
        sub     b,a
        asr     #$3,a,a
        add     x0,a
        move    a,x0
        move    x:(r0),a
        mac     y0,x0,a
        mac     y0,x0,a
        move    a,x:(r0)+
        move    x:(r0),a
        mac     x0,y1,a
        mac     x0,y1,a
        move    a,x:(r0)+
        move    (r1)+n1
hlpairs:
        nop
        bra     hlsung
hlwhole:
        asr     a
        move    a1,n1
        do      #16,>hlones
        move    x:(r1)+n1,x0
        move    x:(r0),a
        mac     y0,x0,a
        mac     y0,x0,a
        move    a,x:(r0)+
        move    x:(r0),a
        mac     x0,y1,a
        mac     x0,y1,a
        move    a,x:(r0)+
hlones:
        nop
hlsung:
        move    r1,x:(r5+$01)
        move    x:(r5+$02),a
        sub     #>$1,a
        move    a,x:(r5+$02)
hlnext:
        move    (r5)+n5
        nop
hlstones:
        nop
        rts
; ---- subroutines (after their callers) ----
hlborn:
; a stone is born in the struct r5 points to
        move    #>$1,a
        move    a,x:(r5)
        move    x:(r7+$02),a
        add     #>$1,a
        move    a,x:(r7+$02)
        move    x:(r5+$10),a
        move    a,x:(r5+$01)
        move    #>$7fffff,a
        move    a,x:(r5+$03)
        clr     a
        move    a,x:(r5+$05)
        move    #>$733333,a
        move    a,x:(r5+$0d)
; speed: 0.5 1 1 1.5 2 (half steps a frame 1 2 2 3 4); with it the longest slice that fits and the attack a word
        bsr     hlrand
        move    #>$5,y0
        mpy     y0,x0,a
        move    a1,a
        cmp     #>$000002,a
        bge     hlspd
        add     #>$1,a
hlspd:
        move    a,x:(r5+$07)
        move    #>$0000a8,x1
        move    #>$0b9c27,y1
        cmp     #>$000001,a
        beq     hlcap
        move    #>$000054,x1
        move    #>$05ce14,y1
        cmp     #>$000002,a
        beq     hlcap
        move    #>$000038,x1
        move    #>$03deb8,y1
        cmp     #>$000003,a
        beq     hlcap
        move    #>$00002a,x1
        move    #>$02e70a,y1
hlcap:
        move    y1,x:(r5+$06)
        move    x1,x:(r7+$06)
; length: (5 .. 30 ms) x SIZE, in calls of 16 frames
        move    #>$7fffff,a
        move    x:(r6+$2),x0
        sub     x0,a
        asr     #$4,a,a                 ; ((128 - v)/64)/32
        move    a1,a
        bsr     hlexp
        move    b,x0
        move    x0,x:(r7+$05)                 ; SIZE / 2
        bsr     hlrand
        move    #>$044e80,y0
        mpy     y0,x0,a
        add     #>$00dc80,a               ; calls x 2^12
        move    a,x0
        move    x:(r7+$05),y0
        mpy     y0,x0,a
        asr     #$b,a,a
        move    a1,a
        move    x:(r7+$06),x0
        cmp     x0,a
        tgt     x0,a
        move    #>$2,x0
        cmp     x0,a
        tlt     x0,a
        move    a,x:(r5+$08)
; words under the envelope = LB x 8 x RATE2; calls to record = (LB x RATE2 + 1)/2 + 1
        move    a,x0
        move    x:(r5+$07),y0
        mpy     y0,x0,a
        asr     a
        move    a0,b
        move    b1,x0                   ; LB x RATE2
        move    x0,a
        add     #>$1,a
        asr     a
        move    a1,a
        add     #>$1,a
        move    a,x:(r5+$02)
        move    x0,b
        asl     #$3,b,b
        move    b,x0
        move    #>$1,a
        bsr     hldiv
        move    b,x:(r5+$04)
; bounces 4 .. 8, first gap 90 .. 220 ms, each next x ratio
        bsr     hlrand
        move    #>$5,y0
        mpy     y0,x0,a
        move    a1,a
        add     #>$4,a
        move    a,x:(r5+$0c)
        bsr     hlrand
        move    #>$001665,y0
        mpy     y0,x0,a
        add     #>$000f81,a
        move    a,x:(r5+$0a)
        bsr     hlrand
        move    #>$147ae1,y0
        mpy     y0,x0,a
        add     #>$4f5c29,a
        move    x:(r6+$3),b
        sub     #>$400000,b
        asr     b
        add     b,a
        move    #>$79999a,x0
        cmp     x0,a
        tgt     x0,a
        move    #>$19999a,x0
        cmp     x0,a
        tlt     x0,a
        move    a,x:(r5+$0b)
; where it falls: pan = (2 u - 1) x WDTH, equal power, x sqrt 2 (held halved)
        bsr     hlrand
        asl     a
        sub     #>$7fffff,a
        move    a,x0
        move    x:(r6+$4),y0
        mpy     y0,x0,a
        move    a,x0
        move    #>$408102,y0
        mpy     y0,x0,a                 ; pan/2
        add     #>$400000,a
        move    a,x0                    ; 0.5 + 0.5 pan
        move    x0,x:(r7+$07)
        bsr     hlsin
        move    a,x0
        move    #>$5a827a,y0
        mpy     y0,x0,a
        asl     a
        move    a,x:(r5+$0f)
        move    #>$7fffff,a
        move    x:(r7+$07),x0
        sub     x0,a
        move    a,x0
        bsr     hlsin
        move    a,x0
        move    #>$5a827a,y0
        mpy     y0,x0,a
        asl     a
        move    a,x:(r5+$0e)
        rts
hlrand:
        move    x:(r7+$01),x0
        move    #>$0343fd,y0
        mpy     y0,x0,a
        asr     a                       ; a1:a0 = the whole product, a0 its low 24 bits
        move    a0,x0
        move    x0,a
        add     #>$269ec3,a
        move    a1,x:(r7+$01)
        move    a1,b
        lsr     b
        move    b1,x0
        move    x0,a
        rts
hlexp:
        move    a1,b
        asr     #$12,a,a  ; a1 = n = floor(y)
        add     #>$1,a
        move    a1,x1  ; n + 1 (never 0: a do count of 0 is not a skip)
        and     #>$03ffff,b
        asl     #$5,b,b  ; f in Q23, b2 stays 0
        move    b1,x0
        move    #>$2c5c86,y0
        mpy     y0,x0,b
        move    b,y0  ; g = f ln2 / 2
        move    #>$02aaab,x0
        mpy     y0,x0,b
        sub     #>$0aaaab,b
        move    b,x0
        mpy     y0,x0,b
        add     #>$200000,b
        move    b,x0
        mpy     y0,x0,b
        sub     #>$400000,b
        move    b,x0
        mpy     y0,x0,b
        add     #>$400000,b  ; e^-g / 2
        move    b,x0
        mpy     x0,x0,b
        asl     #$2,b,b  ; 2^-f in (0.5, 1]
        do      x1,>hlpow
        asr     b
hlpow:
        asl     b
        rts
hlsin:
        mpy     x0,x0,a
        move    a,x1                    ; u^2
        move    #>$04a277,y0
        mpy     x1,y0,a
        add     #>$d6de19,a
        move    a,y0
        mpy     x1,y0,a
        add     #>$648200,a
        move    a,y0
        mpy     y0,x0,a                 ; 0.5 sin(pi u / 2)
        rts
hldiv:
        move    a1,a                    ; a clean 48-bit dividend
        andi    #$fe,ccr
        do      #24,>hlquo
        div     x0,a
hlquo:
        nop
        move    a0,b
        rts
